// Home MedTwins · ponto de entrada (ES module, sem build)
// Inicializa o que é global; cada seção com interação própria entra como módulo em js/secoes/.
import { iniciarRolagem, iniciarAncoras } from './globais/rolagem.js';
import { iniciarNavegacao } from './globais/navegacao.js';
import { iniciarMarcaTexto } from './globais/marca-texto.js';
import { iniciarSurge } from './globais/surge.js';
import { iniciarRodape } from './globais/rodape.js';
